/** True while `at` falls inside the absence: from its start, up to but not including its end. */
export function isAwayAt(absence: MemberAbsence, at: Date): boolean {
  const time = at.getTime();
  return Date.parse(absence.startsAt) <= time && time < Date.parse(absence.endsAt);
}

/** True once `at` has reached the end of the absence. One scheduled for later has not ended. */
export function hasAbsenceEnded(absence: MemberAbsence, at: Date): boolean {
  return at.getTime() >= Date.parse(absence.endsAt);
}

