/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract. An assignee who is
 * away gets the issue handed to their delegate, and the event names the delegate.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const assigneeId = await redirectAssignee(
    actor,
    input.orgId,
    input.assigneeId,
    new Date(),
  );
  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    assigneeId,
  );

  if (assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId,
  });

  return after;
}

/**
 * The assignee an assignment actually lands on. While the assignee is away it
 * is their delegate instead. Taking an issue yourself is never redirected, and
 * the delegate is not redirected again if they are away too.
 */
async function redirectAssignee(
  actor: Actor,
  orgId: OrgId,
  assigneeId: UserId | null,
  at: Date,
): Promise<UserId | null> {
  if (assigneeId === null || assigneeId === actor.userId) return assigneeId;
  return (await delegateWhileAway(orgId, assigneeId, at)) ?? assigneeId;
}

