/**
 * Member absences: who may set them, how they are read, and where assignments,
 * overdue alerts and mentions go while a member is away.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { setAbsenceSchema } from "@/schemas/member";
import type { SetAbsenceInput } from "@/schemas/member";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as absenceRepo from "@/server/repositories/member-absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const HOUR = 60 * 60 * 1000;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

/** A window that covers the present moment. */
function awayNow() {
  const now = Date.now();
  return {
    startsAt: toIsoTimestamp(new Date(now - HOUR)),
    endsAt: toIsoTimestamp(new Date(now + 24 * HOUR)),
  };
}

/** A window that starts tomorrow. */
function scheduledLater() {
  const now = Date.now();
  return {
    startsAt: toIsoTimestamp(new Date(now + 24 * HOUR)),
    endsAt: toIsoTimestamp(new Date(now + 48 * HOUR)),
  };
}

/** A window that ended yesterday. */
function alreadyEnded() {
  const now = Date.now();
  return {
    startsAt: toIsoTimestamp(new Date(now - 48 * HOUR)),
    endsAt: toIsoTimestamp(new Date(now - 24 * HOUR)),
  };
}

function absenceFor(
  tenant: Tenant,
  userId: UserId,
  overrides: Partial<SetAbsenceInput> = {},
): SetAbsenceInput {
  return {
    orgId: tenant.org.id,
    userId,
    delegateUserId: null,
    note: null,
    ...awayNow(),
    ...overrides,
  };
}

async function openIssue(tenant: Tenant) {
  return issueService.createIssue(
    tenant.actors.owner,
    issueInput(tenant.org.id, tenant.project.id, { title: "Plan the launch" }),
  );
}

/** Collects every event of one type for one issue until the test detaches it. */
function collect<K extends "issue.assigned">(type: K, issueId: IssueId): unknown[] {
  const seen: unknown[] = [];
  detachers.push(
    subscribe(type, (payload) => {
      if (payload.issueId === issueId) seen.push(payload);
    }),
  );
  return seen;
}

async function alertsFor(
  tenant: Tenant,
  recipientId: UserId,
  kind: "comment_mention" | "issue_overdue",
) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 50,
    cursor: null,
  });
  return page.items;
}

describe("services/member-service absences", () => {
  it("stores an absence and reads it back as it was stored", async () => {
    const tenant = await createTenant("abs-store");
    const input = absenceFor(tenant, tenant.userIds.member, {
      delegateUserId: tenant.userIds.admin,
      note: "Parental leave",
    });

    const stored = await memberService.setAbsence(tenant.actors.member, input);

    expect(stored).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: "Parental leave",
    });
    expect(
      await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).toEqual(stored);
  });

  it("replaces an earlier absence rather than adding a second", async () => {
    const tenant = await createTenant("abs-replace");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { note: "first" }),
    );
    const second = await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
        note: "second",
      }),
    );

    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toEqual(second);
  });

  it("clears an absence, and clearing again is not an error", async () => {
    const tenant = await createTenant("abs-clear");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member),
    );

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toBeNull();
  });

  it("lets a member change their own absence, but not someone else's without the role right", async () => {
    const tenant = await createTenant("abs-permission");

    await expect(
      memberService.setAbsence(tenant.actors.viewer, absenceFor(tenant, tenant.userIds.member)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.setAbsence(tenant.actors.member, absenceFor(tenant, tenant.userIds.admin)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.admin),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // An admin holds member:update_role, so may set anyone's absence.
    await expect(
      memberService.setAbsence(tenant.actors.admin, absenceFor(tenant, tenant.userIds.member)),
    ).resolves.toMatchObject({ userId: tenant.userIds.member });
  });

  it("rejects an end that is not after the start", async () => {
    const tenant = await createTenant("abs-window");
    const { startsAt } = awayNow();

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceFor(tenant, tenant.userIds.member, { startsAt, endsAt: startsAt }),
      ),
    ).rejects.toThrow(/must end after it starts/);
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceFor(tenant, tenant.userIds.member, {
          startsAt,
          endsAt: toIsoTimestamp(new Date(Date.parse(startsAt) - HOUR)),
        }),
      ),
    ).rejects.toThrow(/must end after it starts/);

    const reversed = {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: null,
      note: null,
      startsAt,
      endsAt: startsAt,
    };
    expect(setAbsenceSchema.safeParse(reversed).success).toBe(false);
    expect(setAbsenceSchema.safeParse(absenceFor(tenant, tenant.userIds.member)).success).toBe(true);
  });

  it("rejects naming oneself as delegate, and requires an active member as delegate", async () => {
    const tenant = await createTenant("abs-delegate");
    const other = await createTenant("abs-delegate-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.member }),
      ),
    ).rejects.toThrow(/own delegate/);
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceFor(tenant, tenant.userIds.member, { delegateUserId: other.userIds.admin }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("returns null once an absence has ended, and returns one scheduled for later", async () => {
    const tenant = await createTenant("abs-timing");

    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, alreadyEnded()),
    );
    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toBeNull();

    const later = await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, scheduledLater()),
    );
    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toEqual(later);
  });

  it("refuses a lookup of a non-member and any operation outside the actor's workspace", async () => {
    const tenant = await createTenant("abs-scope");
    const other = await createTenant("abs-scope-other");

    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.getAbsence(tenant.actors.viewer, other.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.setAbsence(tenant.actors.owner, absenceFor(other, other.userIds.member)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("drops the absence with a removed member, and drops a removed delegate from it", async () => {
    const tenant = await createTenant("abs-remove");
    const owner = tenant.actors.owner;
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceFor(tenant, tenant.userIds.viewer),
    );

    const removedDelegate = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!removedDelegate) throw new Error("fixture member missing");
    await memberService.removeMember(owner, { orgId: tenant.org.id, memberId: removedDelegate.id });

    const kept = await absenceRepo.findAbsence(tenant.org.id, tenant.userIds.member);
    expect(kept).toMatchObject({
      delegateUserId: null,
      startsAt: awayNow().startsAt === kept?.startsAt ? kept.startsAt : kept?.startsAt,
    });
    expect(kept?.delegateUserId).toBeNull();

    const removedMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!removedMember) throw new Error("fixture member missing");
    await memberService.removeMember(owner, { orgId: tenant.org.id, memberId: removedMember.id });

    expect(await absenceRepo.findAbsence(tenant.org.id, tenant.userIds.viewer)).toBeNull();
    await expect(
      memberService.getAbsence(owner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.setAbsence(owner, absenceFor(tenant, tenant.userIds.viewer)),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("keeps workspaces independent for a user who belongs to both", async () => {
    const home = await createTenant("abs-home");
    const away = await createTenant("abs-away");
    await memberRepo.insertMember(away.org.id, home.userIds.member, "member", null);

    await memberService.setAbsence(
      home.actors.member,
      absenceFor(home, home.userIds.member, { delegateUserId: home.userIds.admin }),
    );

    expect(
      await memberService.getAbsence(away.actors.owner, away.org.id, home.userIds.member),
    ).toBeNull();

    const issue = await openIssue(away);
    const assigned = await issueService.assignIssue(away.actors.owner, {
      orgId: away.org.id,
      issueId: issue.id,
      assigneeId: home.userIds.member,
    });
    expect(assigned.assigneeId).toBe(home.userIds.member);
  });
});

describe("assignments while away", () => {
  it("hands an assignment to the delegate and names the delegate in the event", async () => {
    const tenant = await createTenant("abs-assign");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );
    const assigned = collect("issue.assigned", issue.id);

    const result = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(result.assigneeId).toBe(tenant.userIds.admin);
    expect(assigned).toEqual([
      expect.objectContaining({
        previousAssigneeId: null,
        assigneeId: tenant.userIds.admin,
      }),
    ]);
  });

  it("creates an issue for an absent assignee with the delegate as its assignee", async () => {
    const tenant = await createTenant("abs-create");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );

    const created = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Handed over",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(created.assigneeId).toBe(tenant.userIds.admin);
  });

  it("does not redirect before the absence starts", async () => {
    const tenant = await createTenant("abs-scheduled");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
        ...scheduledLater(),
      }),
    );

    const result = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(result.assigneeId).toBe(tenant.userIds.member);
  });

  it("leaves an issue taken by the assignee themselves where it is", async () => {
    const tenant = await createTenant("abs-self");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );

    const result = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(result.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not chain: an absent delegate keeps the issue", async () => {
    const tenant = await createTenant("abs-chain");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceFor(tenant, tenant.userIds.admin, { delegateUserId: tenant.userIds.viewer }),
    );

    const result = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(result.assigneeId).toBe(tenant.userIds.admin);
  });

  it("without a delegate the assignment reaches the absent member", async () => {
    const tenant = await createTenant("abs-no-delegate");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member),
    );

    const result = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(result.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not move issues already assigned when the absence starts", async () => {
    const tenant = await createTenant("abs-existing");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.member,
      }),
    );

    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );

    const [stored] = [await issueService.getIssue(tenant.actors.owner, tenant.org.id, issue.id)];
    expect(stored.issue.assigneeId).toBe(tenant.userIds.member);
  });
});

describe("overdue alerts while away", () => {
  it("sends the overdue alert to the delegate while the assignee is away", async () => {
    const tenant = await createTenant("abs-overdue");
    await usageRepo.recomputeUsage(tenant.org.id);
    const late = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late report",
        assigneeId: tenant.userIds.member,
        dueAt: toIsoTimestamp(new Date(Date.now() - 2 * 24 * HOUR)),
      }),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );

    await runOverdueIssueJob(new Date());

    const forAdmin = await alertsFor(tenant, tenant.userIds.admin, "issue_overdue");
    const forMember = await alertsFor(tenant, tenant.userIds.member, "issue_overdue");
    expect(forAdmin.map((row) => row.href)).toEqual([`/issues/${late.id}`]);
    expect(forMember).toHaveLength(0);
  });

  it("keeps the overdue alert with the assignee when no delegate is set", async () => {
    const tenant = await createTenant("abs-overdue-solo");
    await usageRepo.recomputeUsage(tenant.org.id);
    const late = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late, no delegate",
        assigneeId: tenant.userIds.member,
        dueAt: toIsoTimestamp(new Date(Date.now() - 2 * 24 * HOUR)),
      }),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member),
    );

    await runOverdueIssueJob(new Date());

    const forMember = await alertsFor(tenant, tenant.userIds.member, "issue_overdue");
    expect(forMember.map((row) => row.href)).toEqual([`/issues/${late.id}`]);
  });
});

describe("mentions while away", () => {
  it("alerts both the mentioned member and their delegate while they are away", async () => {
    const tenant = await createTenant("abs-mention");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );

    await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Over to you",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    });

    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);
  });

  it("alerts a delegate who is mentioned directly only once", async () => {
    const tenant = await createTenant("abs-mention-once");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );

    await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Both of you, please",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.admin],
    });

    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
  });

  it("never alerts the author, even when the author is the delegate", async () => {
    const tenant = await createTenant("abs-mention-author");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, { delegateUserId: tenant.userIds.admin }),
    );

    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Picking this up",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    });

    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
  });

  it("alerts only the member when they are not away", async () => {
    const tenant = await createTenant("abs-mention-present");
    const issue = await openIssue(tenant);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceFor(tenant, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
        ...scheduledLater(),
      }),
    );

    await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Over to you",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    });

    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
  });
});

